import * as React from "react";
import type { HeadFC, PageProps } from "gatsby";
import { graphql } from "gatsby";
import { useI18next, useTranslation } from "gatsby-plugin-react-i18next";
import { useEffect } from "react";
import Link from "../../components/AppLink";
import ExtractiveServiceSummary, {
  type ExtractiveServiceSummaryContent,
} from "../../components/ExtractiveServiceSummary";
import I18nHeadProvider from "../../components/I18nHeadProvider";
import Layout from "../../components/Layout";
import ProofHighlights from "../../components/ProofHighlights";
import SEO from "../../components/seo";
import data from "../../data/data.json";
import type { Company } from "../../interfaces";
import images from "../../images";
import {
  buildBreadcrumbListSchema,
  buildFAQPageSchema,
  localizeSitePath,
} from "../../utils/structuredData";
import { trackCtaClick } from "../../utils/analytics";

const info: Company = data[0];

type Chip = { chip: string };
type Card = { title: string; text: string };
type ListItem = { item: string };
type Step = { title: string; text: string };
type Faq = { q: string; a: string };
type HighlightItem = {
  eyebrow?: string;
  title: string;
  text: string;
  href?: string;
  ctaLabel?: string;
};

const AiSearchOptimizationPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();

  useEffect(() => {
    document.body.style.backgroundImage = `url(${images.bg.src})`;
    document.body.style.backgroundSize = "cover";
    document.body.style.backgroundPosition = "center";
    document.body.style.backgroundRepeat = "no-repeat";

    return () => {
      document.body.style.backgroundImage = "";
      document.body.style.backgroundSize = "";
      document.body.style.backgroundPosition = "";
      document.body.style.backgroundRepeat = "";
    };
  }, []);

  const heroChips = t("services.aiSearchOptimization.hero.chips", {
    returnObjects: true,
  }) as Chip[];
  const extractive = t("services.aiSearchOptimization.sections.extractive", {
    returnObjects: true,
  }) as ExtractiveServiceSummaryContent;
  const outcomes = t("services.aiSearchOptimization.sections.outcomes.items", {
    returnObjects: true,
  }) as Card[];
  const idealFor = t("services.aiSearchOptimization.sections.idealFor.items", {
    returnObjects: true,
  }) as ListItem[];
  const deliverables = t(
    "services.aiSearchOptimization.sections.deliverables.items",
    { returnObjects: true }
  ) as ListItem[];
  const steps = t("services.aiSearchOptimization.sections.process.steps", {
    returnObjects: true,
  }) as Step[];
  const faq = t("services.aiSearchOptimization.sections.faq.items", {
    returnObjects: true,
  }) as Faq[];
  const proofItems = t("services.sharedProof.items", {
    returnObjects: true,
  }) as HighlightItem[];
  const relatedResources = t(
    "services.aiSearchOptimization.sections.relatedResources",
    {
      returnObjects: true,
    }
  ) as {
    title: string;
    subtitle?: string;
    items: HighlightItem[];
  };

  const mailSubject = encodeURIComponent(
    t("services.aiSearchOptimization.hero.emailSubject") ||
      "AI Search Optimization Inquiry"
  );
  const mailto = `mailto:${info.email}?subject=${mailSubject}`;

  return (
    <Layout data={info}>
      <section className="pt-10 pb-6 sm:pt-14 sm:pb-10">
        <div className={styles.container}>
          <div className="text-center">
            <h1 className="text-3xl sm:text-5xl poppins-bold text-light mx-auto max-w-4xl">
              {t("services.aiSearchOptimization.hero.title")}
            </h1>

            <p className="mt-4 text-lg sm:text-2xl poppins-regular text-light/90 mx-auto max-w-4xl">
              {t("services.aiSearchOptimization.hero.subtitle")}
            </p>

            <div className="mx-auto mt-8 flex flex-col sm:flex-row items-center justify-center gap-3">
              <Link
                to="/contact/"
                className="rounded-full bg-secondary px-5 py-2.5 text-light text-center"
                onClick={() => {
                  void trackCtaClick({
                    cta_name: "ai_search_hero_primary",
                    cta_location: "ai_search_hero",
                    destination: "/contact/",
                    destination_type: "internal",
                  });
                }}
              >
                {t("services.aiSearchOptimization.hero.primaryCta")}
              </Link>

              <a
                href={mailto}
                className="rounded-full bg-purplesemilight px-5 py-2.5 text-dark font-semibold text-center"
                onClick={() => {
                  void trackCtaClick({
                    cta_name: "ai_search_hero_secondary",
                    cta_location: "ai_search_hero",
                    destination: mailto,
                    destination_type: "mailto",
                  });
                }}
              >
                {t("services.aiSearchOptimization.hero.secondaryCta")}
              </a>
            </div>

            {Array.isArray(heroChips) && heroChips.length > 0 ? (
              <div className="mx-auto mt-6 flex flex-wrap items-center justify-center gap-2 max-w-4xl">
                {heroChips.map((chip, index) => (
                  <span
                    key={`${chip.chip}-${index}`}
                    className="inline-flex items-center rounded-full border border-white/20 bg-white/10 px-3 py-1 text-sm text-light/90"
                  >
                    {chip.chip}
                  </span>
                ))}
              </div>
            ) : null}
          </div>
        </div>
      </section>

      <ProofHighlights
        title={t("services.sharedProof.title") as string}
        subtitle={t("services.sharedProof.subtitle") as string}
        items={proofItems}
      />

      <ExtractiveServiceSummary content={extractive} />

      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
            {t("services.aiSearchOptimization.sections.outcomes.title")}
          </h2>

          <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-4">
            {Array.isArray(outcomes)
              ? outcomes.map((item, index) => (
                  <div key={`${item.title}-${index}`} className={styles.card}>
                    <h3 className={styles.cardTitle}>{item.title}</h3>
                    <p className={styles.cardText}>{item.text}</p>
                  </div>
                ))
              : null}
          </div>
        </div>
      </section>

      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
            {t("services.aiSearchOptimization.sections.idealFor.title")}
          </h2>

          <div className="mt-8 mx-auto max-w-4xl">
            <ul className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              {Array.isArray(idealFor)
                ? idealFor.map((item, index) => (
                    <li key={`${item.item}-${index}`} className={styles.card}>
                      <p className="text-sm sm:text-base text-light/80">
                        {item.item}
                      </p>
                    </li>
                  ))
                : null}
            </ul>
          </div>
        </div>
      </section>

      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
            {t("services.aiSearchOptimization.sections.deliverables.title")}
          </h2>

          <div className="mt-8 mx-auto max-w-4xl">
            <div className={styles.card}>
              <ul className="list-disc pl-5 space-y-2 text-sm sm:text-base text-light/80">
                {Array.isArray(deliverables)
                  ? deliverables.map((item, index) => (
                      <li key={`${item.item}-${index}`}>{item.item}</li>
                    ))
                  : null}
              </ul>
            </div>
          </div>
        </div>
      </section>

      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
            {t("services.aiSearchOptimization.sections.process.title")}
          </h2>

          <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-4">
            {Array.isArray(steps)
              ? steps.map((step, index) => (
                  <div key={`${step.title}-${index}`} className={styles.card}>
                    <div className="flex items-center gap-3">
                      <span className="inline-flex h-7 w-7 items-center justify-center rounded-full border border-black/10 bg-white text-sm font-semibold text-dark/70">
                        {index + 1}
                      </span>
                      <h3 className={styles.cardTitle}>{step.title}</h3>
                    </div>
                    <p className={styles.cardText}>{step.text}</p>
                  </div>
                ))
              : null}
          </div>
        </div>
      </section>

      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
            {t("services.aiSearchOptimization.sections.faq.title")}
          </h2>

          <div className="mt-8 mx-auto max-w-4xl space-y-3">
            {Array.isArray(faq)
              ? faq.map((item, index) => (
                  <details key={`${item.q}-${index}`} className={styles.card}>
                    <summary className="cursor-pointer text-sm sm:text-base font-semibold text-light/90">
                      {item.q}
                    </summary>
                    <p className={styles.cardText}>{item.a}</p>
                  </details>
                ))
              : null}
          </div>
        </div>
      </section>

      <ProofHighlights
        title={relatedResources?.title}
        subtitle={relatedResources?.subtitle}
        items={Array.isArray(relatedResources?.items) ? relatedResources.items : []}
      />

      <section className="py-12 sm:py-16">
        <div className={styles.container}>
          <div className="mx-auto max-w-4xl text-center">
            <h2 className="text-2xl sm:text-4xl poppins-regular text-verde">
              {t("services.aiSearchOptimization.sections.finalCta.title")}
            </h2>
            <p className="mt-4 text-sm sm:text-base text-light/70">
              {t("services.aiSearchOptimization.sections.finalCta.subtitle")}
            </p>

            <div className="mt-8 flex flex-col sm:flex-row items-center justify-center gap-3">
              <Link
                to="/contact/"
                className="rounded-full bg-secondary px-5 py-2.5 text-light text-center"
                onClick={() => {
                  void trackCtaClick({
                    cta_name: "ai_search_final_primary",
                    cta_location: "ai_search_final_cta",
                    destination: "/contact/",
                    destination_type: "internal",
                  });
                }}
              >
                {t("services.aiSearchOptimization.sections.finalCta.primaryCta")}
              </Link>

              <a
                href={mailto}
                className="rounded-full bg-purplesemilight px-5 py-2.5 text-dark font-semibold text-center"
                onClick={() => {
                  void trackCtaClick({
                    cta_name: "ai_search_final_secondary",
                    cta_location: "ai_search_final_cta",
                    destination: mailto,
                    destination_type: "mailto",
                  });
                }}
              >
                {t(
                  "services.aiSearchOptimization.sections.finalCta.secondaryCta"
                )}
              </a>
            </div>
          </div>
        </div>
      </section>
    </Layout>
  );
};

const AiSearchOptimizationHeadContent: React.FC = () => {
  const { t } = useTranslation();
  const { language, defaultLanguage } = useI18next();
  const faq = t("services.aiSearchOptimization.sections.faq.items", {
    returnObjects: true,
  }) as Faq[];
  const faqSchema = buildFAQPageSchema(faq);
  const breadcrumbSchema = buildBreadcrumbListSchema(info.url, [
    {
      name: t("menu.home") as string,
      path: localizeSitePath("/", language, defaultLanguage),
    },
    {
      name: t("menu.servicesHub.nav") as string,
      path: localizeSitePath("/services/", language, defaultLanguage),
    },
    {
      name: t("menu.services.aiSearchOptimization.nav") as string,
      path: localizeSitePath(
        "/services/ai-search-optimization/",
        language,
        defaultLanguage
      ),
    },
  ]);
  const additionalSchemas = [breadcrumbSchema, faqSchema].filter(
    Boolean
  ) as object[];

  return (
    <SEO
      data={info}
      titleKey="services.aiSearchOptimization.metaTitle"
      descriptionKey="services.aiSearchOptimization.metaDescription"
      pathname="/services/ai-search-optimization/"
      image={images.what_is_geo_ai_search_optimization.src}
      schemaType="ProfessionalService"
      pageSchemaType="Service"
      additionalSchemas={additionalSchemas.length ? additionalSchemas : undefined}
    />
  );
};

export const Head: HeadFC = ({ data, pageContext }) => (
  <I18nHeadProvider data={data} pageContext={pageContext}>
    <AiSearchOptimizationHeadContent />
  </I18nHeadProvider>
);

export default AiSearchOptimizationPage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  container: "mx-auto w-full max-w-6xl px-4 sm:px-6",
  card: "rounded-2xl border border-black/10 bg-primary/70 p-5 shadow-sm supports-[backdrop-filter]:bg-purplesemilight/40 supports-[backdrop-filter]:backdrop-blur text-light",
  cardTitle: "text-base sm:text-lg font-semibold text-light/90",
  cardText: "mt-3 text-sm sm:text-base text-light/70 leading-relaxed",
};
